# Carry-over (2026-10-29): previously-shown deals that dropped out of Query 1 only because SF
# Total_ACV_Value__c went to $0 (renewal netting, LastModified 2026-10-27). Kept on the dashboard
# with live fields (q1carry.json) and flagged each run until Liron confirms force-include or removal.
CARRY_OVER = ['006i9000001o9HFAAY', '006i9000001pcnRAAQ']  # ANZ NCCR DEV / QA renewals 2026
FIELDS = ['id', 'name', 'close', 'acv', 'cur', 'account', 'top', 'owner', 'region', 'agents',
          'exp_gl', 'pm_gl', 'pm_est', 'ctype', 'om', 'ttu']


def d(s):
    return datetime.date.fromisoformat(s) if s else None


def waterfall(o, p, today):
    """Return (status, date) per the Go-Live waterfall."""
    ttu = o['ttu']
    end = d(p[4]) if p else None
    status = p[1] if p else None
    actual = p[2] if p else None
    far = end is not None and end > today + datetime.timedelta(days=30)
    if o['om'] and ttu is not None:
        return 'Live', None
    if ttu is not None and not far:
        return 'Live', None
    if status == '2 - Closed' and actual and ttu is not None:
        return 'Live', None
    if far:
        return 'Delayed', p[4]
    eta = (p[3] if p else None) or o['pm_est'] or o['exp_gl']
    if eta:
        return ('Delayed', eta) if d(eta) < today else ('ETA', eta)
    return 'TBD', None


def build(Q, today):
    q1 = Q['q1a'] + Q['q1b'] + Q['q1c']
    opps = {}
    for r in q1:
        if r[0] not in FORCE_EXCLUDE:
            opps.setdefault(r[0], dict(zip(FIELDS, r)))
    force = {r[0]: dict(zip(FIELDS, r)) for r in Q['q1force']}
    for fid in FORCE_INCLUDE:
        if fid in force:
            opps[fid] = force[fid]  # live fields from Query 1b
    for r in Q.get('q1carry', []):
        if r[0] in CARRY_OVER and r[0] not in FORCE_EXCLUDE and r[0] not in opps:
            opps[r[0]] = dict(zip(FIELDS, r))
    projects = {}
    for p in Q['q2']:
        projects.setdefault(p[0], p)
    offline = (set(Q['q3']) | FORCE_OFFLINE)
    rt = (set(Q['q4']) | FORCE_RT) - NEVER_RT
    q5 = {}
    for oid, code in Q['q5']:
        lab = 'SmartReach' if code.startswith('610346-3070') else 'Ticketing' if code.startswith('610346-3071') else 'AMC'
        q5.setdefault(oid, set()).add(lab)
    q6 = {}
    for oid, code in Q['q6']:
        lab = 'AutoSummary' if code.startswith(('1550-3927', '1550-3926')) else 'Copilot'
        q6.setdefault(oid, set()).add(lab)
    acd_of = {}
    for lab in ACD_ORDER:
        for i in ACD[lab]:
            acd_of.setdefault(i, []).append(lab)

    rows = []
    for oid, o in opps.items():
        is_off, is_rt = oid in offline, oid in rt
        hub = 'RT + Offline' if (is_off and is_rt) else 'Offline' if is_off else 'Real-Time'
        badges = []
        if oid not in FORCE_NO_INTEGRATION:
            if hub in ('Offline', 'RT + Offline'):
                integ = set(q5.get(oid, set()))
                if oid in FORCE_SMARTREACH: integ.add('SmartReach')
                if oid in FORCE_TICKETING: integ.add('Ticketing')
                if oid in TICKETING_ONLY: integ = {'Ticketing'}
                badges += [b for b in ('SmartReach', 'Ticketing', 'AMC') if b in integ]
            if hub in ('Real-Time', 'RT + Offline'):
                badges += acd_of.get(oid, [])
            badges += [b for b in ('AutoSummary', 'Copilot') if b in q6.get(oid, set())]
        if oid in GL_OVERRIDE:
            gl, gld = GL_OVERRIDE[oid]
        else:
            gl, gld = waterfall(o, projects.get(oid), today)
        acct = o['account'].replace('’', "'")
        acct = ACCOUNT_CLEAN.get(acct, acct)
        name = NAME_BY_ID.get(oid) or NAME_CLEAN.get(o['name'], o['name'])
        name = name.replace('’', "'")
        rows.append(dict(
            id=oid, account=acct, group=o['top'] or acct, name=name, type=o['ctype'], badges=badges,
            hub=hub, close=o['close'], acv=float(o['acv'] or 0), cur=o['cur'],
            agents=AGENTS_OVERRIDE.get(oid, o['agents']), region=o['region'] or REGION_FILL.get(oid) or '',
            gl=gl, gldate=gld, owner=OWNER_CLEAN.get(o['owner'], o['owner'])))
    rows.sort(key=lambda r: r['close'], reverse=True)
    return rows


def new_deal_candidates(Q, rows):
    final = {r['id'] for r in rows}
    return [i for i in Q['qN'] if i not in final and i not in FORCE_EXCLUDE and i not in IGNORE_LIST]


def render_html(rows, template, today):
    data = json.dumps(rows, ensure_ascii=False).replace('</', '<\\/')
    return template.replace('__DATA__', data).replace('__GENDATE__', today.isoformat())


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('--data')
    ap.add_argument('--out', default='ehub-dashboard-static.html')
    ap.add_argument('--today', default=datetime.date.today().isoformat())
    a = ap.parse_args()
    today = d(a.today)
    if a.data:
        Q = {k: json.load(open(os.path.join(a.data, k + '.json'))) for k in DATA_FILES}
        for k in OPTIONAL_FILES:
            if os.path.exists(os.path.join(a.data, k + '.json')):
                Q[k] = json.load(open(os.path.join(a.data, k + '.json')))
    else:
        Q = QUERY_DATA
    rows = build(Q, today)
    open(a.out, 'w', encoding='utf-8').write(render_html(rows, TEMPLATE, today))
    cands = new_deal_candidates(Q, rows)
    json.dump(dict(rows=rows, candidates=cands), open(a.out + '.rows.json', 'w'), ensure_ascii=False)
    print('deals', len(rows), 'candidates', cands)
    return rows, cands



